{"content": "import warnings
from fastapi.responses import ORJSONResponse, UJSONResponse

def test_deprecation_warnings():
    with warnings.catch_warnings(record=True) as w:
        warnings.simplefilter("always")

        # Test ORJSONResponse
        try:
            ORJSONResponse({"message": "hello"})
        except Exception as e:
            print(f"Caught expected exception for ORJSONResponse: {e}")

        orjson_warning = [warn for warn in w if "ORJSONResponse is deprecated" in str(warn)]
        print(f"ORJSONResponse warning: {orjson_warning}")

        # Test UJSONResponse
        try:
            UJSONResponse({"message": "hello"})
        except Exception as e:
            print(f"Caught expected exception for UJSONResponse: {e}")

        ujson_warning = [warn for warn in w if "UJSONResponse is deprecated" in str(warn)]
        print(f"UJSONResponse warning: {ujson_warning}")

        assert len(orjson_warning) > 0, "ORJSONResponse deprecation warning not triggered"
        assert len(ujson_warning) > 0, "UJSONResponse deprecation warning not triggered"
        print("All deprecation warnings triggered successfully!")

if __name__ == "__main__":
    try:
        test_deprecation_warnings()
    except Exception as e:
        print(f"Error: {e}")
        exit(1)
", "filepath": "test_deprecation.py"}

